DASHBOARD_ENTRY = '        ("Domain Split",\n         "test_domain_split.py",\n         "Check that the provenance scanner\'s whole-tree Tier-1 total prints "\n         "with its split by domain (orrery, Earth System, stars, ...), the "\n         "same on the console, in PROVENANCE_AUDIT.md and in the run history; "\n         "that each module\'s domain is read from the Domain: tag in its own "\n         "docstring; and that a file with no tag is named, not counted as "\n         "orrery. Scans small made-up modules in a temporary folder and writes "\n         "nothing in the project. Six faults are planted first, each caught by "\n         "name. Ends on \\"DOMAIN SPLIT: PASS\\" (L-437).",\n         SCRIPT_DIR,\n         True,\n         None,\n         True),\n'

DASHBOARD_STAMP = 'October 13, 2026 with Anthropic\'s Claude Opus 5.5 (L-437): Domain Split\nunder the orrery\'s checkers, in the same patch as its checker\ntest_domain_split.py, with the same name as its maintenance-run row (the\nbutton is named what the run prints). It sits before Drawings Export,\nits alphabetical place once the labels lose "Test".\n'

NEW_FILES = [
    ('test_domain_split.py',
     '"""\ntest_domain_split.py - Checks for L-437: the provenance scanner\'s\nwhole-tree Tier-1 total prints with its domain split, and a module\'s\ndomain is read from its own docstring Domain: tag.\n\nRun from the project directory (VS Code: open this file, click Run):\n    python test_domain_split.py\n\nExits 0 if every check holds and every planted fault is caught, 1\notherwise. The maintenance run executes it as a gating checker,\n"Domain Split", and its last line starts "DOMAIN SPLIT:".\n\nWHAT IT CHECKS\n--------------\nTony, 2026-10-12: "the provenance checker is still reporting 288 tier 1\nitems. Can we separate this into meaningful groups, like orrery, earth\nscience and stars in the checker report?" The split existed in the\naudit\'s Findings by File Type table, and the total travelled without\nit. And a module\'s domain had two homes: the scanner\'s hand list,\nMODULE_DOMAIN_MAP, and the Domain: tag in each module\'s docstring,\nwhich the atlas reads. They disagreed on 12 files at c5dff25.\n\nSix checks, each on a small tree of synthetic modules written to a\ntemporary folder and scanned there, so they do not depend on the real\nmodules\' findings, and nothing in the project folder is written:\n\n  1. the tag is the domain: a file tagged stars is filed as stars, even\n     under the name data_acquisition, which the old hand list filed as\n     orrery; and the hand list is gone from the scanner.\n  2. a file with no Domain: tag, and one with a tag outside the six,\n     are counted as unclassified and named in the audit\'s coverage-gap\n     note with the reason -- never defaulted into orrery.\n  3. the whole-tree line on the console, the line in the audit\'s\n     Priority Summary, the run history\'s tier1_by_domain and the Tier 1\n     column of the audit\'s Findings by File Type table all give the\n     same split, and it sums to the total.\n  4. one finding moved between domains at an unchanged total changes\n     the printed line, and the run history names the move (A Check That\n     Cannot Fail Is Not Passing, its fourth move: the delta names what\n     moved).\n  5. the maintenance run\'s scanner row quotes the GATE PATH line first\n     and the whole-tree line after it, and says so when either is\n     missing.\n  6. the run history keeps domain_counts as the all-tier count and\n     tier1_by_domain as the Tier-1 count, two fields for two questions.\n\nPLANTED FAULTS\n--------------\nBefore the checks are trusted, six faults are planted, one at a time,\nby swapping a function for a broken one inside this process (nothing\non disk changes), and each must make a named check fail:\n\n  F1 the hand list back: every module filed as orrery.\n  F2 an untagged file defaulted to orrery, not named.\n  F3 the total printed without its split.\n  F4 the run history written without tier1_by_domain.\n  F5 the run history\'s comparison blind to domains.\n  F6 the scanner row quoting the gate line only.\n\nThen the real functions are restored and the checks must all pass.\n\nDesign: plain assert functions, no pytest; main() prints a summary.\n\nModule created: October 13, 2026 with Anthropic\'s Claude Opus 5.5\n(L-437, patch_L437_1_tier1_by_domain_20261013.py).\n\nRole: devtool\nDomain: dev_tools\n"""\n\nimport contextlib\nimport io\nimport json\nimport os\nimport re\nimport shutil\nimport sys\nimport tempfile\nimport traceback\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nif HERE not in sys.path:\n    sys.path.insert(0, HERE)\n\nimport provenance_scanner as ps\nimport provenance_history as ph\nimport orrery_maintenance_run as omr\n\n\n# ============================================================\n# A SMALL TREE TO SCAN\n# ============================================================\n# Each module carries one display string with an uncited figure, which\n# the scanner scores Tier-1. The docstring tag is the only thing that\n# says which domain it belongs to.\n\ndef _module(domain_line, note):\n    head = \'"""A synthetic module for test_domain_split.py.\\n\\nRole: data\\n\'\n    if domain_line:\n        head += domain_line + \'\\n\'\n    return head + \'"""\\nNOTE = "%s"\\n\' % note\n\n\nNOTES = {\n    \'o1\': \'The probe passed 12,000 km above the surface at 9.5 km/s.\',\n    \'o2\': \'The moon orbits 384,400 km out, at 1.02 km/s.\',\n    \'s1\': \'The star lies 4.2 light-years away, at 1.2 solar radii.\',\n    \'e1\': \'The heat wave reached 48 C on 5 days and displaced 2,000 people.\',\n}\n\nBASE_TREE = {\n    \'orbit_one.py\': _module(\'Domain: orrery\', NOTES[\'o1\']),\n    \'orbit_two.py\': _module(\'Domain: orrery\', NOTES[\'o2\']),\n    # The name the old hand list filed as orrery; the tag says stars.\n    \'data_acquisition.py\': _module(\'Domain: stars\', NOTES[\'s1\']),\n    \'heat_wave.py\': _module(\'Domain: earth_science\', NOTES[\'e1\']),\n}\n\n\ndef _write_tree(files):\n    tmp = tempfile.mkdtemp(prefix=\'domainsplit_\')\n    for name, text in files.items():\n        with open(os.path.join(tmp, name), \'w\', encoding=\'ascii\',\n                  newline=\'\\n\') as handle:\n            handle.write(text)\n    return tmp\n\n\ndef _scan(tmp):\n    """Scan a tree; return (console text, audit text, history dict)."""\n    audit = os.path.join(tmp, \'AUDIT.md\')\n    buf = io.StringIO()\n    with contextlib.redirect_stdout(buf):\n        ps.scan_project(tmp, audit)\n    with open(audit, encoding=\'utf-8\') as handle:\n        audit_text = handle.read()\n    with open(ph.history_path(tmp), encoding=\'utf-8\') as handle:\n        history = json.load(handle)\n    return buf.getvalue(), audit_text, history\n\n\n# ============================================================\n# READING THE FOUR PLACES\n# ============================================================\n\nSHORT_TO_KEY = dict((short, key) for key, short in ps.DOMAIN_SHORT)\nLABEL_TO_KEY = dict((label, key) for key, label in ps.DOMAIN_LABELS.items())\n\n\ndef _parse_split_text(text):\n    """\'5: orrery 2, stars 1\' -> (5, {\'orrery\': 2, \'stars\': 1})."""\n    m = re.match(r\'\\s*(\\d+)(?::\\s*(.*))?$\', text.strip().rstrip(\'.\'))\n    assert m, \'not a whole-tree split: %r\' % text\n    total = int(m.group(1))\n    split = {}\n    for part in (m.group(2) or \'\').split(\',\'):\n        part = part.strip()\n        if not part:\n            continue\n        name, count = part.rsplit(\' \', 1)\n        assert name in SHORT_TO_KEY, \'unknown domain %r in %r\' % (name, text)\n        split[SHORT_TO_KEY[name]] = int(count)\n    return total, split\n\n\ndef _console_split(console):\n    lines = [l for l in console.splitlines() if \'Whole tree, Tier-1:\' in l]\n    assert len(lines) == 1, \'console whole-tree lines: %r\' % lines\n    return _parse_split_text(lines[0].split(\'Whole tree, Tier-1:\', 1)[1])\n\n\ndef _audit_split(audit):\n    m = re.search(r\'\\*\\*Whole tree, Tier-1: (.*?)\\.\\*\\*\', audit)\n    assert m, "the audit\'s Priority Summary has no whole-tree split"\n    return _parse_split_text(m.group(1))\n\n\ndef _table_split(audit):\n    """The Tier 1 column of Findings by File Type, nonzero domains."""\n    section = audit.split(\'## Findings by File Type\', 1)[1].split(\'\\n---\', 1)[0]\n    split = {}\n    for line in section.splitlines():\n        cells = [c.strip() for c in line.strip().strip(\'|\').split(\'|\')]\n        if len(cells) != 7 or not cells[2].isdigit():\n            continue\n        label = cells[0]\n        key = LABEL_TO_KEY.get(label)\n        if key is None and label.startswith(\'Unclassified\'):\n            key = ps.UNCLASSIFIED\n        assert key, \'unknown table row %r\' % label\n        if int(cells[2]):\n            split[key] = int(cells[2])\n    return split\n\n\ndef _history_split(history):\n    rec = history[\'runs\'][-1]\n    raw = rec.get(\'tier1_by_domain\')\n    assert raw is not None, \'the run record carries no tier1_by_domain\'\n    return int(rec[\'tier_counts\'][\'1\']), dict(\n        (k, int(v)) for k, v in raw.items() if int(v))\n\n\n# ============================================================\n# THE CHECKS\n# ============================================================\n\ndef check_tag_is_the_domain():\n    """data_acquisition.py tagged stars is filed as stars."""\n    assert not hasattr(ps, \'MODULE_DOMAIN_MAP\'), \\\n        \'the hand list MODULE_DOMAIN_MAP is still in the scanner\'\n    tmp = _write_tree(BASE_TREE)\n    try:\n        domain, problem = ps.classify_domain(\n            \'data_acquisition\', os.path.join(tmp, \'data_acquisition.py\'))\n        assert (domain, problem) == (\'stars\', None), (domain, problem)\n        _console, audit, _history = _scan(tmp)\n        row = [l for l in audit.splitlines()\n               if l.startswith(\'| `data_acquisition.py`\')]\n        assert row and \'| stars |\' in row[0], \\\n            \'data_acquisition.py is not filed as stars: %r\' % row\n        assert _table_split(audit).get(\'stars\') == 1, _table_split(audit)\n    finally:\n        shutil.rmtree(tmp, ignore_errors=True)\n\n\ndef check_untagged_is_named_not_defaulted():\n    """No tag and an unknown tag: unclassified, and named with why."""\n    files = dict(BASE_TREE)\n    files[\'mystery.py\'] = _module(None, NOTES[\'o1\'])\n    files[\'odd_one.py\'] = _module(\'Domain: astro\', NOTES[\'o2\'])\n    tmp = _write_tree(files)\n    try:\n        _console, audit, _history = _scan(tmp)\n        split = _table_split(audit)\n        assert split.get(ps.UNCLASSIFIED) == 2, split\n        assert split.get(\'orrery\') == 2, \\\n            \'an untagged file was counted as orrery: %r\' % split\n        gap = audit.split(\'**Domain coverage gap\', 1)\n        assert len(gap) == 2, \'no coverage-gap note in the audit\'\n        note = gap[1].split(\'\\n---\', 1)[0]\n        assert \'`mystery.py` -- no Domain: tag\' in note, note\n        assert \'`odd_one.py` -- Domain: astro is not one of the six\' in note, \\\n            note\n    finally:\n        shutil.rmtree(tmp, ignore_errors=True)\n\n\ndef check_four_places_agree():\n    """Console, audit line, history field and table column agree."""\n    tmp = _write_tree(BASE_TREE)\n    try:\n        console, audit, history = _scan(tmp)\n        c_total, c_split = _console_split(console)\n        a_total, a_split = _audit_split(audit)\n        h_total, h_split = _history_split(history)\n        t_split = _table_split(audit)\n        assert c_total == a_total == h_total == 4, (c_total, a_total, h_total)\n        assert sum(t_split.values()) == 4, t_split\n        assert c_split == a_split == h_split == t_split, \\\n            \'console %r, audit %r, history %r, table %r\' % (\n                c_split, a_split, h_split, t_split)\n        assert t_split == {\'orrery\': 2, \'stars\': 1, \'earth_science\': 1}, \\\n            t_split\n    finally:\n        shutil.rmtree(tmp, ignore_errors=True)\n\n\ndef check_a_move_at_equal_total_shows():\n    """One finding retagged from orrery to stars: same total, a\n    different line, and the history names the move."""\n    tmp = _write_tree(BASE_TREE)\n    try:\n        console1, _audit1, _history1 = _scan(tmp)\n        with open(os.path.join(tmp, \'orbit_two.py\'), \'w\', encoding=\'ascii\',\n                  newline=\'\\n\') as handle:\n            handle.write(_module(\'Domain: stars\', NOTES[\'o2\']))\n        console2, _audit2, _history2 = _scan(tmp)\n        t1, s1 = _console_split(console1)\n        t2, s2 = _console_split(console2)\n        assert t1 == t2 == 4, (t1, t2)\n        assert s1 != s2, \'the line did not change when a finding moved\'\n        moved = [l for l in console2.splitlines() if \'MOVED by domain\' in l]\n        assert moved, \'the run history did not name the move\'\n        assert \'orrery 2 -> 1\' in moved[0] and \'stars 1 -> 2\' in moved[0], \\\n            moved[0]\n    finally:\n        shutil.rmtree(tmp, ignore_errors=True)\n\n\ndef check_maintenance_row_quotes_both():\n    """The scanner row: the gate line first, the whole-tree line after."""\n    rows = [r for r in omr.CHECKERS if r[1] == [\'provenance_scanner.py\']]\n    assert len(rows) == 1, \'scanner rows: %r\' % rows\n    hint = rows[0][2]\n    assert isinstance(hint, tuple) and hint[0] == \'GATE PATH:\' \\\n        and \'Whole tree, Tier-1:\' in hint, hint\n    output = (\'  GATE PATH: 0 TIER-1 -- the push gate holds\\n\'\n              \'  Whole tree, Tier-1: 4: orrery 2, stars 1, Earth System 1.\\n\')\n    note = omr.verdict_from(output, hint)\n    assert note.startswith(\'0 TIER-1 -- the push gate holds; \'), note\n    assert \'Whole tree, Tier-1: 4: orrery 2, stars 1, Earth System 1.\' \\\n        in note, note\n    missing = omr.verdict_from(\'  GATE PATH: 0 TIER-1\\n\', hint)\n    assert \'no "Whole tree, Tier-1" line printed\' in missing, missing\n    rows = [r for r in omr.CHECKERS if r[1] == [\'test_domain_split.py\']]\n    assert len(rows) == 1 and rows[0][0] == \'Domain Split\' \\\n        and rows[0][2] == \'DOMAIN SPLIT:\', rows\n\n\ndef check_history_keeps_two_fields():\n    """domain_counts is all tiers; tier1_by_domain is Tier-1 only."""\n    from datetime import datetime, timezone\n    now = datetime.now(timezone.utc)\n    rec = ph.make_run_record(now, now, \'.\', 3, 10, {1: 2, 3: 8},\n                             {\'orrery\': 10}, {\'a.py\': 2},\n                             tier1_by_domain={\'orrery\': 2})\n    assert rec[\'domain_counts\'] == {\'orrery\': 10}, rec[\'domain_counts\']\n    assert rec[\'tier1_by_domain\'] == {\'orrery\': 2}, rec[\'tier1_by_domain\']\n    old = dict(rec)\n    old.pop(\'tier1_by_domain\')\n    d = ph.compare(old, rec)\n    assert d[\'domains\'][\'known\'] is False, d[\'domains\']\n    text = \'\\n\'.join(ph.domain_delta_lines(old, rec, d[\'domains\']))\n    assert \'predates L-437\' in text, text\n\n\nCHECKS = [\n    check_tag_is_the_domain,\n    check_untagged_is_named_not_defaulted,\n    check_four_places_agree,\n    check_a_move_at_equal_total_shows,\n    check_maintenance_row_quotes_both,\n    check_history_keeps_two_fields,\n]\n\n\n# ============================================================\n# THE PLANTED FAULTS\n# ============================================================\n# (name, target module, attribute, broken replacement builder, the\n# check that must fail). Each replacement wraps or replaces the real\n# function in memory only; the original is put back afterwards.\n\ndef _hand_list_back(real):\n    def broken(module_name, filepath=None):\n        return \'orrery\', None\n    return broken\n\n\ndef _untagged_defaults(real):\n    def broken(module_name, filepath=None):\n        domain, problem = real(module_name, filepath)\n        if domain == ps.UNCLASSIFIED:\n            return \'orrery\', None\n        return domain, problem\n    return broken\n\n\ndef _total_only(real):\n    def broken(total, split):\n        return \'%d\' % total\n    return broken\n\n\ndef _history_drops_split(real):\n    def broken(*args, **kwargs):\n        rec = real(*args, **kwargs)\n        rec.pop(\'tier1_by_domain\', None)\n        return rec\n    return broken\n\n\ndef _compare_blind(real):\n    def broken(prev, cur):\n        out = real(prev, cur)\n        out[\'domains\'] = {\'known\': True, \'moved\': []}\n        return out\n    return broken\n\n\ndef _gate_line_only(real):\n    def broken(output, hint):\n        first = hint[0] if isinstance(hint, tuple) else hint\n        return real(output, first)\n    return broken\n\n\nFAULTS = [\n    (\'F1 the hand list back\', ps, \'classify_domain\', _hand_list_back,\n     check_tag_is_the_domain),\n    (\'F2 untagged defaulted to orrery\', ps, \'classify_domain\',\n     _untagged_defaults, check_untagged_is_named_not_defaulted),\n    (\'F3 the total without its split\', ps, \'whole_tree_split_text\',\n     _total_only, check_four_places_agree),\n    (\'F4 history without tier1_by_domain\', ph, \'make_run_record\',\n     _history_drops_split, check_four_places_agree),\n    (\'F5 history blind to domains\', ph, \'compare\', _compare_blind,\n     check_a_move_at_equal_total_shows),\n    (\'F6 the row quotes the gate only\', omr, \'verdict_from\',\n     _gate_line_only, check_maintenance_row_quotes_both),\n]\n\n\ndef run_fault(name, module, attr, builder, check):\n    """True when the planted fault makes its check fail.\n\n    Only counted as caught when the same check passes on the real\n    functions (main() runs those first): a check that fails anyway\n    would "catch" every fault and prove nothing.\n    """\n    real = getattr(module, attr)\n    setattr(module, attr, builder(real))\n    try:\n        check()\n    except AssertionError:\n        return True\n    finally:\n        setattr(module, attr, real)\n    return False\n\n\n# ============================================================\n# RUNNER\n# ============================================================\n\ndef main():\n    print(\'=\' * 70)\n    print(\'test_domain_split.py -- L-437: the whole-tree Tier-1 total and \'\n          \'its domains\')\n    print(\'=\' * 70)\n    # The real functions first, so a fault is counted as caught only\n    # by a check that passes without it.\n    passed, failed = 0, []\n    report = []\n    for check in CHECKS:\n        try:\n            check()\n            passed += 1\n            report.append(\'  PASS  %s\' % check.__name__)\n        except Exception:                                 # noqa: BLE001\n            failed.append(check.__name__)\n            report.append(\'  FAIL  %s -- %s\' % (\n                check.__name__, traceback.format_exc(limit=1).strip()\n                .splitlines()[-1]))\n    print(\'Planted faults (each must make its check fail):\')\n    missed = []\n    for name, module, attr, builder, check in FAULTS:\n        if check.__name__ in failed:\n            caught = False\n            verdict = \'VOID  \'\n        else:\n            try:\n                caught = run_fault(name, module, attr, builder, check)\n            except Exception:                             # noqa: BLE001\n                caught = False\n                traceback.print_exc(limit=1)\n            verdict = \'CAUGHT\' if caught else \'MISSED\'\n        print(\'  %s  %-38s by %s\' % (verdict, name, check.__name__))\n        if not caught:\n            missed.append(name)\n    print()\n    print(\'Checks on the real functions:\')\n    for line in report:\n        print(line)\n    print(\'=\' * 70)\n    print(\'Results: %d of %d faults caught; %d of %d checks pass\'\n          % (len(FAULTS) - len(missed), len(FAULTS), passed, len(CHECKS)))\n    if missed or failed:\n        print(\'DOMAIN SPLIT: FAILED -- %s\'\n              % \', \'.join(missed + failed))\n        return 1\n    print(\'DOMAIN SPLIT: PASS -- %d of %d planted faults caught; the \'\n          \'split reads each module\\\'s Domain: tag and prints the same on \'\n          \'the console, in the audit and in the run history.\'\n          % (len(FAULTS), len(FAULTS)))\n    return 0\n\n\nif __name__ == \'__main__\':\n    sys.exit(main())\n'),
    ('documentation/HANDOFF_L437_tier1_by_domain_20261013.md',
     '<!-- Doc-Kind: hand | Session record for L-437: the provenance scanner\'s whole-tree Tier-1 total now prints with its domain split everywhere it prints, and a module\'s domain is read from its own docstring tag (the hand list retired). Build session, one patch. -->\n# L-437: the Tier-1 total prints with its domains (build record)\n\nBuilt on orrery 70202e3bff79136fe6561aab60d42f57b193eda9 at\nhttps://github.com/tonylquintanilla/palomas_orrery ("maintenance").\nThe gallery is not touched.\nTony\'s local folders: orrery\n`C:\\Users\\tonyq\\OneDrive\\Desktop\\python_work\\palomas_orrery_for_github\\`;\ngallery `C:\\Users\\tonyq\\OneDrive\\Desktop\\python_work\\tonyquintanilla.github.io\\`.\nWritten October 13, 2026 with Anthropic\'s Claude Opus 5.5.\n\n- Type: BUILD. One patch, `patch_L437_1_tier1_by_domain_20261013.py`,\n  saved in the orrery\'s root folder.\n- Brief: `documentation/HANDOFF_L437_tier1_by_domain_brief_20261013.md`\n  (cut at 400a9615), read after\n  `documentation/HANDOFF_scaffolding_sessions_coordination_20261013.md`.\n- Ledger: L-437 opened by this patch, status OPEN until Tony\'s run.\n- Skills loaded and checked against the manifest at 70202e3b:\n  provenance-discipline 2.28, safe-file-editing 1.13, agentic-pre-test\n  1.3, ledger-and-session-records 1.20. All four matched.\n\n## 1. What Tony asked\n\nTony, 2026-10-12: "the provenance checker is still reporting 288 tier 1\nitems. Can we separate this into meaningful groups, like orrery, earth\nscience and stars in the checker report?"\n\nAfter this patch the scanner\'s last block reads, on the tree at\n70202e3b:\n\n    GATE PATH: 0 TIER-1 -- the push gate holds\n    ...\n    Whole tree, Tier-1: 281: orrery 116, Earth System 149, stars 13, utilities 2, unclassified 1.\n\nThe same line opens the audit\'s Priority Summary, closes its Gate Path\nsection, sits in the run history, and is the second half of the\nmaintenance run\'s Provenance scanner row.\n\n## 2. Measured at HEAD, before building\n\n- Whole tree 281 Tier-1; gate path 0. (The brief\'s 280 was at\n  400a9615. The 281st is `patch_L436_1_idea_20261013.py`, which sits\n  unrun in the root and is scanned there.)\n- By the scanner\'s hand list, MODULE_DOMAIN_MAP: orrery 118, Earth\n  System 149, stars 12, utilities 2.\n- By each module\'s docstring Domain: tag: orrery 116, Earth System 149,\n  stars 13, utilities 2, and 1 in a file with no tag.\n- The two homes disagreed on 14 files with findings:\n  - `data_acquisition.py`: tagged stars; its one Tier-1 was counted as\n    orrery.\n  - `patch_L436_1_idea_20261013.py`: no tag; its one Tier-1 was counted\n    as orrery.\n  - twelve dev tools filed as orrery, with 38 findings between them,\n    all Tier 3: `test_orbit_markers.py`, `test_position_digits.py`,\n    `worksheet_checker.py`, `orrery_maintenance_run.py`,\n    `doc_index.py`, `worksheet_request_builder.py`,\n    `export_constants.py`, `export_drawings.py`, `export_objects.py`,\n    `test_dimensions.py`, `worksheet_key_aliases.py`,\n    `worksheet_keys.py`.\n- Eighteen files with findings were in no hand-list entry and printed\n  as the "Domain coverage gap".\n- Every root module carries a Domain: tag except the unrun L-436 patch,\n  and only the six words are in use (orrery 51, dev_tools 47, stars 27,\n  earth_science 19, utilities 7, gallery 1).\n\n## 3. What the patch changes\n\n- `provenance_scanner.py`. MODULE_DOMAIN_MAP is gone. classify_domain()\n  reads the module\'s own Domain: tag through\n  module_atlas.classify_domain(), the reader the atlas uses, and is\n  given the file\'s path in the scanned tree. A file with no tag, or a\n  tag outside the six, is counted as UNCLASSIFIED: its own row in\n  Findings by File Type, shown at zero when clean, and named in the\n  "Domain coverage gap" note with its reason. When there is no gap the\n  note says how many files it checked. The whole-tree total prints with\n  its split on the console, in the Priority Summary and in the Gate\n  Path section, all from one count, tier1_by_domain(). If the domains\n  ever failed to sum to the total, the line would say so in capitals\n  rather than print a split that does not add up. In passing: a stray\n  closing line of the August Task 2a stamp, which had drifted below the\n  L-414 stamp, is put back under Task 2a.\n- `provenance_history.py`. Each run record gains `tier1_by_domain`\n  beside `domain_counts`. compare() names each domain whose Tier-1\n  count moved; the console prints the split and the move after the\n  Tier-1 delta; the Run History table gains a "T1 by domain" column.\n  A record from before L-437 reads "--" and is called not comparable,\n  never zero.\n- `orrery_maintenance_run.py`. The Provenance scanner row\'s hint is now\n  two lines, the GATE PATH verdict first and the whole-tree line after\n  it, joined by "; ". A hint may be a tuple, read by a new\n  verdict_from(); a line it names that the output lacks prints as\n  missing. New gating row "Domain Split".\n- `test_domain_split.py`, new (described in section 4).\n- `palomas_orrery_dashboard.py`. A "Domain Split" button under the\n  orrery\'s checkers, before Drawings Export, named what the run prints.\n- `skills/provenance-discipline/SKILL.md` 2.28 -> 2.29 (section 6), its\n  v2.26 entry moved to `documentation/SKILL_HISTORIES.md`; in\n  `references/field-notes.md` one example that named the hand list as\n  current now names it as retired.\n- `PROJECT_INSTRUCTIONS.md` v3.95; v3.92 moved to\n  `documentation/PROJECT_INSTRUCTIONS_HISTORY.md` PART 1.\n- `LEDGER_CONSOLIDATED.md`: the L-437 block at the end of section A, one\n  stamp line above "Review and RICE update".\n- `documentation/WHERE_WE_ARE.md`: the Signals line only. The page\n  stays at 130 lines above the run-record marker.\n- This handoff, new.\n\nReport-only. No finding moves between tiers.\n\n## 4. The checker, and the planted faults\n\n`test_domain_split.py`, row and button "Domain Split", last line\n"DOMAIN SPLIT:". It writes small made-up modules to a temporary folder,\neach with one uncited figure the scanner scores Tier-1, scans them\nthere, and reads the result. Nothing in the project folder is written.\n\nSix checks:\n1. The tag is the domain: a file named `data_acquisition.py`, tagged\n   stars, is filed as stars; MODULE_DOMAIN_MAP no longer exists.\n2. A file with no tag and one tagged "astro" are counted as\n   unclassified and named, each with its reason; neither is counted\n   as orrery.\n3. The console line, the audit\'s Priority Summary line, the run\n   history\'s tier1_by_domain and the Tier 1 column of Findings by File\n   Type give the same split, and it sums to the total.\n4. One file retagged from orrery to stars between two scans: the total\n   stays 4, the printed line changes, and the history prints "Tier-1\n   MOVED by domain: orrery 2 -> 1, stars 1 -> 2".\n5. The maintenance run\'s scanner row quotes the GATE PATH line first\n   and the whole-tree line after it, and says when the second is\n   missing; the Domain Split row is named what it prints.\n6. The run record keeps domain_counts (all tiers) and tier1_by_domain\n   (Tier 1) as two fields; a record without the split is not\n   comparable.\n\nSix faults, each planted in memory by swapping one function, and each\ncounted as caught only by a check that passes on the real code (the\nchecker\'s first draft counted a fault as caught by a check that failed\nanyway; that is fixed):\n\n    F1 the hand list back                  by check_tag_is_the_domain\n    F2 untagged defaulted to orrery        by check_untagged_is_named_not_defaulted\n    F3 the total without its split         by check_four_places_agree\n    F4 history without tier1_by_domain     by check_four_places_agree\n    F5 history blind to domains            by check_a_move_at_equal_total_shows\n    F6 the row quotes the gate only        by check_maintenance_row_quotes_both\n\nThe brief\'s planted cases map onto these: data_acquisition.py filed by\nits tag (check 1, F1; and the real file, section 5); a file with no\ntag named in the gap (check 2, F2; and the real L-436 patch, section\n5); the four places agreeing with the table (check 3, F3, F4); a move\nat an unchanged total changing the line (check 4, F5).\n\n## 5. The pre-test\n\nRun on throwaway copies of 70202e3b with the patch applied; the\ndeliverable is never edited by the pre-test. Results in section 9.\n\n## 6. The skill, and L-425\n\nprovenance-discipline goes to 2.29, one version, with protocol v3.95\nin the same patch; the maintenance run rewrites the Skill Manifest.\nReport Domain Classification is rewritten: the tag is the store, the\nhand list is gone, the gap note names untagged files. Scanner\nMechanics gains one bullet: the total prints with its split\neverywhere, and tier1_by_domain is Tier-1 while domain_counts is all\ntiers.\n\nThe brief asked which happened with L-425. At 70202e3b\nprovenance-discipline reads 2.28 and no L-425 patch is in the repo, so\nthis build bumps it. If the L-425 session also bumps\nprovenance-discipline before this patch runs, the second patch to run\nrefuses on the version line; that session re-anchors on the new HEAD\nand makes its version 2.30. Nothing is hand-edited.\n\n## 7. Notes for the parallel sessions\n\n- `patch_L436_1_idea_20261013.py` will refuse at 70202e3b on its ledger\n  header anchor: it expects the stamp built on c9722520 to be the last\n  one before "Review and RICE update", and two stamps have been added\n  since. Its other four anchors match. That patch is its own session\'s\n  to redeliver; this patch does not depend on it, and the two touch\n  different lines of the page.\n- The maintenance run\'s GATING AND REPORT-ONLY paragraph still says\n  twenty-five gating checkers. This patch makes it twenty-six, the\n  dashboard-labels patch adds a parity row and L-425 adds rows. This\n  patch does not edit that sentence, so no patch refuses on it; the\n  one that runs last restates the count.\n- Row and button share one name, "Domain Split", in title case, as the\n  dashboard rule asks. The dashboard button is inserted by finding the\n  `test_drawings_export.py` entry, not by its label, so the labels\n  build can rename that button first without this patch refusing.\n\n## 8. Recorded, not edited here\n\n- L-183 says "the remaining unmapped-root-modules question still rides\n  with this item." L-437 answers it: no module is mapped by hand any\n  more.\n- L-163\'s deferred Domain half, retiring MODULE_DOMAIN_MAP, is done.\n- `add_docstrings.py` line 823 names MODULE_DOMAIN_MAP in a comment\n  about where its suggestions came from. It is history, and not\n  edited.\n- Older documents in `documentation/` name MODULE_DOMAIN_MAP as\n  current. They are dated records.\n\n## 9. The pre-test, as run\n\nAll on throwaway clones of 70202e3b, in the sandbox, Python 3.12 under\na virtual display.\n- The patch applied: 69 edits in 11 files and 2 new files. The tree it\n  produced is byte for byte the build copy this session worked in.\n- The maintenance run on that copy: 26 of 26 gating checkers passed.\n  Domain Split: "PASS -- 6 of 6 planted faults caught". Scanner row\n  run: 16 of 16 pins hold. The Provenance scanner row read "0 TIER-1\n  -- the push gate holds; Whole tree, Tier-1: 281: orrery 116, Earth\n  System 149, stars 13, utilities 2, unclassified 1." It rewrote the\n  Skill Manifest to provenance-discipline 2.29 and the skill\'s read\n  plan.\n- A second scanner run printed "Tier-1 by domain: orrery 116, Earth\n  System 149, stars 13, utilities 2, unclassified 1" and "no domain\'s\n  Tier-1 count moved"; the first run after the patch says the previous\n  record predates L-437, as it should.\n- The real audit, against the committed one at 70202e3b:\n  `data_acquisition.py` reads stars (orrery before);\n  `patch_L436_1_idea_20261013.py` reads unclassified and is the one\n  file in the coverage-gap note; `orrery_maintenance_run.py` reads\n  dev_tools. Stars: 12 files and 13 Tier-1 (11 and 12 before).\n- This patch, while it sits in the root, adds no finding of its own.\n  The atlas lists it under "Patch scripts awaiting archive", as its\n  `Role: patch` tag says.\n- Run a second time, the patch refuses and writes nothing ("this patch\n  looks as though it has already run"). On a copy where another\n  session had renamed the Drawings Export button, renamed a maintenance\n  row, added a ledger stamp and marked the Signals heading, with three\n  files turned CRLF, it applied, reported the three, and wrote them LF.\n- The dashboard on a copy under a virtual display: "Dashboard ready",\n  no traceback, closed by the 25-second timeout.\n- ASCII and LF: 0 non-ASCII bytes and 0 CRLF in all 14 files.\n- Not a finding: the sandbox\'s first baseline run at HEAD failed Reset\n  completeness and Orbit markers because matplotlib was not installed\n  there. With it installed, both pass.\n\n## 10. Tony\'s actions, all of them\n\n- (do) Run `patch_L437_1_tier1_by_domain_20261013.py` from the orrery\'s\n  root folder (VS Code, Run).\n- (do) Run `orrery_maintenance_run.py`. Read the Provenance scanner\n  row: the gate line, then "Whole tree, Tier-1: 281: orrery 116, Earth\n  System 149, stars 13, utilities 2, unclassified 1." (280 and no\n  unclassified once patch_L436_1 is filed in `documentation/`; this\n  patch adds no Tier-1 of its own while it sits in the root). Read\n  Domain Split: 6 of 6 faults caught.\n- (do) Reinstall provenance-discipline 2.29 (Settings > Skills); copy\n  PROJECT_INSTRUCTIONS.md (v3.95) to the Project\'s instructions and to\n  `documentation/project_instructions_v3_95.md`.\n- (do) Move this patch into `documentation/`; commit and push.\n- The next session confirms its loaded provenance-discipline reads\n  2.29 before provenance work.\n- (decide) Nothing.\n\nSession record written October 2026 with Anthropic\'s Claude Opus 5.5.\n'),
]


def _read(rel, texts, crlf):
    if rel not in texts:
        path = os.path.join(ROOT, rel)
        if not os.path.exists(path):
            print('ERROR: %s not found in %s. NOTHING was written.' % (rel, ROOT))
            return None
        raw = open(path, 'rb').read()
        if b'\r\n' in raw:
            crlf.add(rel)
        texts[rel] = raw.replace(b'\r\n', b'\n').decode('utf-8')
    return texts[rel]


def apply():
    texts, crlf, done = {}, set(), []
    for rel, text in NEW_FILES:
        path = os.path.join(ROOT, rel)
        if os.path.exists(path):
            same = open(path, 'rb').read().replace(b'\r\n', b'\n').decode('utf-8') == text
            print('ERROR: %s already exists%s. NOTHING was written.'
                  % (rel, ' (this patch looks as though it has already run)' if same else ''))
            return None
    for rel, label, old, new in EDITS:
        t = _read(rel, texts, crlf)
        if t is None:
            return None
        n = t.count(old)
        if n != 1:
            print('ANCHOR FAIL  %-45s %s (found %d times, expected 1). NOTHING was written.'
                  % (rel, label, n))
            return None
        if MARKER in t and t.index(old) > t.index(MARKER):
            print('ANCHOR FAIL  %-45s %s lies below the run-record marker. NOTHING was written.'
                  % (rel, label))
            return None
        texts[rel] = t.replace(old, new)
        done.append((rel, label))
    # The dashboard: placed by structure, not by a label another session
    # may rename.
    t = _read(DASHBOARD, texts, crlf)
    if t is None:
        return None
    key = '"test_drawings_export.py",'
    if t.count(key) != 1 or '"test_domain_split.py"' in t:
        print('ANCHOR FAIL  %-45s the Drawings Export entry (found %d times, expected 1)%s. '
              'NOTHING was written.' % (DASHBOARD, t.count(key),
                                        '; Domain Split is already there'
                                        if '"test_domain_split.py"' in t else ''))
        return None
    i = t.index(key)
    s = t.rindex('\n        (', 0, i) + 1
    t = t[:s] + DASHBOARD_ENTRY + t[s:]
    done.append((DASHBOARD, 'checkers: the Domain Split button'))
    e = t.index('\n"""', 3) + 1
    t = t[:e] + DASHBOARD_STAMP + t[e:]
    done.append((DASHBOARD, 'docstring: L-437 stamp'))
    texts[DASHBOARD] = t
    for rel, label, old, new in EDITS:
        if any(ord(c) > 127 for c in new):
            print('ERROR: an edit to %s would add non-ASCII. NOTHING was written.' % rel)
            return None
    # The page's cap: lines above the run-record marker.
    page = texts.get('documentation/WHERE_WE_ARE.md')
    if page is not None and MARKER in page:
        above = page[:page.index(MARKER)].count('\n')
        if above > 130:
            print('ERROR: WHERE_WE_ARE.md would have %d lines above the marker (cap 130). '
                  'NOTHING was written.' % above)
            return None
    for rel, t in texts.items():
        with open(os.path.join(ROOT, rel), 'w', encoding='utf-8', newline='') as h:
            h.write(t)
    for rel, text in NEW_FILES:
        with open(os.path.join(ROOT, rel), 'w', encoding='utf-8', newline='') as h:
            h.write(text)
        done.append((rel, 'new file'))
    for rel, label in done:
        print('ok  %-45s %s' % (rel, label))
    for rel in sorted(crlf):
        print('note: %s was CRLF in the working copy; written LF' % rel)
    print()
    print('patch applied (%d edits in %d files, %d new files)'
          % (len(done) - len(NEW_FILES), len(texts), len(NEW_FILES)))
    print('Stamps updated: provenance_scanner.py, provenance_history.py,')
    print('orrery_maintenance_run.py, palomas_orrery_dashboard.py, the skill\'s')
    print('version line, the protocol\'s header and anchor, the ledger.')
    print('Fixed in passing: in provenance_scanner.py\'s docstring, the closing line')
    print('of the August Task 2a stamp, which sat below the L-414 stamp, is back')
    print('under Task 2a.')
    if page is not None:
        print('WHERE_WE_ARE.md: %d lines above the run-record marker (cap 130).' % above)
    return True


def main():
    if not apply():
        return 1
    print()
    print('NEXT:')
    print('  1. Run orrery_maintenance_run.py. Expect every gating checker to pass (26 at 70202e3b')
    print('     with this patch; more if another session\'s patch has added rows), "Domain Split"')
    print('     with 6 of 6 planted faults caught, and the Provenance scanner row reading:')
    print('       0 TIER-1 -- the push gate holds; Whole tree, Tier-1: 281: orrery 116,')
